from taf.ul.kpi_selector.operations.operation_prototype.operation_prototype import OperationPrototype


class RfUnlock(OperationPrototype):
    def __init__(self, bts):
        super(RfUnlock, self).__init__(bts)
        self.operation_details = {
            "Timeout": 0,
            "Operation": "RF lock procedure via BTS OAM",
            "Start point": "RF lock request sent",
            "End point": "RF is locked",
            "Requirement": "-",
        }

    def get_kpi(self):
        """
        Gets RF unlock procedure timeout
        KPI: Flexi Radio RP1 Interface Specification, 3.3 Timeouts for procedures
        :return: dictionary with timeout, requirement and operation description for RF unlock
        :rtype: dict
        """
        self.operation_details["Timeout"] += 60
        self.operation_details["Requirement"] = "Flexi Radio RP1 Interface Specification, 3.3 Timeouts for procedures"

        return self.operation_details
